import { formatDay, type Copy } from "./copy";
import { escapeHtml } from "./layout";
import { EMBER_HTML, EMBER_TEXT, TRIAL_STRINGS } from "./trial-pack";

/**
 * The free-trial messages, from the copy pack in trial-3-giorni/testi (ember
 * template, kit layout v2; strings per product and language, regenerated by
 * scripts/trial-pack.mjs). They go only to subscriptions sold with our trial.
 * "renewal_payment_failed" is the pack's payment-failed message reworded for a
 * renewal: with trials switched on, a failed renewal also suspends Pro at once,
 * and the older plan-ending notice would wrongly say Pro keeps working.
 */
export type TrialMailKind =
  | "trial_started" | "trial_ending" | "trial_paid" | "trial_payment_failed" | "renewal_payment_failed" | "trial_ended";

const SECTION: Record<TrialMailKind, string> = {
  trial_started: "ts", trial_ending: "te", trial_paid: "pa",
  trial_payment_failed: "pf", renewal_payment_failed: "pf", trial_ended: "tx",
};

export type Money = { minor: number; currency: string };

export type TrialMailInput = {
  product: string;
  firstName: string;
  email: string;
  plan: string | null;
  /** Started/ending: when the trial ends. Ended: when it ended. */
  trialEnd?: Date | null;
  /** Started/ending: the first charge as Stripe previews it. Paid: what was
   *  taken. Payment failed: what could not be taken. Coupon and tax included. */
  amount?: Money | null;
  /** Paid: the next renewal. */
  renewsOn?: Date | null;
  card?: { brand: string; last4: string } | null;
  /** Payment failed: a key of common.failureReasons (see failureKey). */
  failure?: string | null;
  /** Payment failed: where the payment method is updated. */
  portalUrl?: string | null;
  /** Ended: cancelled during the trial, or no payment method at its end. */
  reason?: "cancelled" | "no_method";
};

/** Trial moments carry their zone, so any reader can place them. */
export const TRIAL_TIME_ZONE = "Europe/Rome";

/** "17 October 2026, 14:05 (CEST)" in the reader's language. */
export function trialMoment(locale: string, date: Date): string {
  const day = new Intl.DateTimeFormat(locale, { day: "numeric", month: "long", year: "numeric", timeZone: TRIAL_TIME_ZONE }).format(date);
  const parts = new Intl.DateTimeFormat(locale, {
    hour: "2-digit", minute: "2-digit", hourCycle: "h23", timeZone: TRIAL_TIME_ZONE, timeZoneName: "short",
  }).formatToParts(date);
  const part = (type: string) => parts.find((p) => p.type === type)?.value ?? "";
  return `${day}, ${part("hour")}:${part("minute")} (${part("timeZoneName")})`;
}

/** An amount in the reader's language: "€3.99", "3,99 €". */
export function trialMoney(locale: string, { minor, currency }: Money): string {
  return new Intl.NumberFormat(locale, { style: "currency", currency: currency.toUpperCase() }).format(minor / 100);
}

const CARD_BRANDS: Record<string, string> = {
  visa: "Visa", mastercard: "Mastercard", amex: "American Express", discover: "Discover", diners: "Diners Club",
  jcb: "JCB", unionpay: "UnionPay", cartes_bancaires: "Cartes Bancaires", eftpos_au: "eftpos", interac: "Interac",
};

/** Stripe's last payment error, as a key of common.failureReasons. */
export function failureKey(error: { code?: string | null; decline_code?: string | null } | null | undefined, needsAction = false): string {
  const decline = error?.decline_code ?? "";
  const code = error?.code ?? "";
  if (decline === "insufficient_funds") return "insufficient_funds";
  if (decline === "expired_card" || code === "expired_card") return "expired_card";
  if (needsAction || decline === "authentication_required" || code === "authentication_required") return "authentication_required";
  if (decline === "processing_error" || code === "processing_error") return "processing_error";
  if (decline || code === "card_declined") return "card_declined";
  return "generic";
}

export function trialMail(kind: TrialMailKind, input: TrialMailInput, c: Copy): { subject: string; html: string; text: string } {
  const product = input.product === "uninstaller" ? "uninstaller" : "pctweaker";
  const t = TRIAL_STRINGS[product][c.tag] ?? TRIAL_STRINGS[product].en;
  const common = t.common as Record<string, string>;
  const reasons = t.common.failureReasons as Record<string, string>;
  const e = { ...t[SECTION[kind]] } as Record<string, string>;
  if (kind === "trial_ended") {
    const cancelled = input.reason !== "no_method";
    e.intro = cancelled ? e.introCancelled : e.introNoMethod;
    e.r1Value = cancelled ? e.r1ValueCancelled : e.r1ValueNoMethod;
  }
  if (kind === "renewal_payment_failed") {
    e.intro = e.introRenewal;
    e.why = e.whyRenewal;
  }
  const locale = common.dateLocale;
  const brand = input.card ? CARD_BRANDS[input.card.brand] ?? input.card.brand.charAt(0).toUpperCase() + input.card.brand.slice(1) : "";
  const moment = input.trialEnd ? trialMoment(locale, input.trialEnd) : null;
  const amount = input.amount ? trialMoney(locale, input.amount) : null;
  const vars: Record<string, string | null> = {
    firstName: input.firstName,
    email: input.email,
    planLabel: c.plans[input.plan ?? ""] ?? c.plans.monthly,
    trialEndsOn: moment,
    trialEndedOn: moment,
    chargeAmount: amount,
    chargedLabel: amount,
    renewsOn: input.renewsOn ? formatDay(c, input.renewsOn) : null,
    paymentMethodLabel: input.card
      ? common.paymentMethodCard.replace("${brand}", brand).replace("${last4}", input.card.last4)
      : common.paymentMethodFallback,
    failureReason: reasons[input.failure ?? "generic"] ?? reasons.generic,
    portalUrl: input.portalUrl ?? null,
  };
  // A value the message needs but does not have fails the delivery, which is
  // retried: nothing half-filled ever reaches a customer.
  const fill = (text: string) =>
    (input.firstName ? text : text.replace(/, \$\{firstName\}/g, "")).replace(/\$\{(\w+)\}/g, (_, key: string) => {
      const value = vars[key];
      if (!value) throw new Error(`trial mail ${kind}: no value for ${key}`);
      return value;
    });
  const render = (template: string, html: boolean) =>
    template.replace(/\{\{([ce])\.(\w+)\}\}/g, (_, scope: string, key: string) => {
      const value = (scope === "c" ? common : e)[key];
      if (typeof value !== "string") throw new Error(`trial mail ${kind}: no string ${scope}.${key}`);
      if (!html || key.endsWith("Html")) return html ? value : fill(value);
      return escapeHtml(fill(value));
    });
  return { subject: fill(e.subject), html: render(EMBER_HTML, true), text: render(EMBER_TEXT, false) };
}
